effect.shader:
float gT = 0.0;

vec3 sat3v(vec3 c){ return clamp(c, vec3(0.0), vec3(1.0)); }
float lum(vec3 c){ return dot(c, vec3(0.2126, 0.7152, 0.0722)); }

// LAYER -> SCREEN. The whole treatment - grain, weave, bloom, vignette - is
// measured in layer space, so it stays welded to the layer.
// Positions are anchored on acScreenNorm - the engine's own screen position for
// this fragment - so the anchor never depends on the matrix. Only the DELTA goes
// through acLayerToScreen, and the w=0 multiply cancels the translation, so a
// layer-space offset becomes a screen-space offset exactly. fetchL(acLayerNorm)
// therefore returns texture2DCv(inputImg.texture, acScreenNorm), the engine idiom.
vec2 lpToScreen(vec2 v){ return acScreenNorm + (vec4(v - acLayerNorm, 0.0, 0.0) * acLayerToScreen).xy; }
vec4 fetchL(vec2 lp){ return texture2DCv(inputImg.texture, clamp(lpToScreen(lp), 0.0, 1.0)); }
vec3 strL(vec2 lp){ vec4 s = fetchL(lp); return s.rgb / max(s.a, 1e-4); }

float h21(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }

// Bright-pass sample: only what is above the threshold contributes to the bloom,
// which is what stops the whole frame washing out.
vec3 brightAt(vec2 lp){
vec4 s = fetchL(lp);
vec3 c = s.rgb / max(s.a, 1e-4);
return max(c - vec3(glowThreshold), vec3(0.0));
}

void main(){
vec2 lp  = acLayerNorm;

gT = mix(acTime, floor(acTime * 12.0) / 12.0, clamp(frameStep, 0.0, 1.0));

// ---- gate weave ---------------------------------------------------------
// The projector never sits still, so the frame is sampled from a jittered
// position. Two noise channels at different speeds so it drifts rather than
// vibrates.
vec2 woff = vec2(0.0);
if (weave > 0.001){
woff = vec2(h21(vec2(floor(gT * weaveSpeed), 1.0)) - 0.5,
            h21(vec2(floor(gT * weaveSpeed), 2.0)) - 0.5) * weave * 0.020;
}
vec2 slp = lp + woff;

vec4 src = fetchL(slp);
float al = max(src.a, 1.0e-4);
vec3 sc  = src.rgb / al;
float l  = lum(sc);

// ---- grade --------------------------------------------------------------
vec3 c = mix(vec3(l), sc, clamp(1.0 - desaturate, 0.0, 1.0));

if (flashMode <= 0){
// Sepia Memory - the classic warm monochrome.
c = mix(c, vec3(l * 1.14, l * 0.98, l * 0.72), 0.85);
} else if (flashMode <= 1){
// Bleach Bypass - keep the colour but drop the saturation and lift contrast.
c = mix(vec3(l), sc, 0.35);
c = sat3v((c - vec3(0.5)) * 1.35 + vec3(0.5));
} else if (flashMode <= 2){
c = mix(c, vec3(l * 1.12, l * 0.95, l * 0.70), 0.60);
} else if (flashMode <= 3){
c = mix(c, vec3(l * 0.86, l * 0.98, l * 1.16), 0.60);
} else {
c = mix(c, vec3(l * 1.04, l * 0.99, l * 0.88), 0.55);
}
c = sat3v(c);
c = mix(c, vec3(0.5), clamp(fade, 0.0, 1.0) * 0.35);

// ---- bloom --------------------------------------------------------------
if (glow > 0.001){
float rad = glowRadius / max(acLayerSize.y, 1.0);
vec3 acc = vec3(0.0);
float wsum = 0.0;
for (int i = 0; i < 12; i++){
float a  = float(i) * 0.5235988;
vec2  d  = vec2(cos(a), sin(a));
acc += brightAt(slp + d * rad) * 1.0;
wsum += 1.0;
acc += brightAt(slp + d * rad * 0.45) * 0.6;
wsum += 0.6;
}
vec3 bl = acc / max(wsum, 1.0e-4);
c += bl * glow * 1.25;
}

// ---- flicker ------------------------------------------------------------
if (flicker > 0.001){
float fl = h21(vec2(floor(gT * flickerSpeed), 17.3));
c *= 1.0 + (fl - 0.5) * flicker * 0.55;
}

// ---- emulsion: scratches and dust --------------------------------------
// Both are gated by a per-frame hash, so they come and go the way real
// print damage does instead of sitting on the frame.
if (scratches > 0.001){
for (int i = 0; i < 12; i++){
if (float(i) >= float(scratchCount)) break;
float fr = floor(gT * 9.0);
// Gate factor instead of continue: the loop body always runs, the result is
// simply zeroed on the frames where this scratch is not present.
float on = (h21(vec2(float(i) * 3.3, fr)) < 0.72) ? 1.0 : 0.0;
float sx = h21(vec2(float(i) * 13.7, fr * 3.1));
float w  = 0.0012 + h21(vec2(float(i), 7.7)) * 0.0022;
c += vec3((1.0 - smoothstep(0.0, w, abs(lp.x - sx))) * scratches * 0.55 * on);
}
}

if (dust > 0.001){
for (int i = 0; i < 10; i++){
float fr = floor(gT * 10.0);
float on = (h21(vec2(float(i) * 5.1 + 3.0, fr)) < 0.70) ? 1.0 : 0.0;
vec2  dp  = vec2(h21(vec2(float(i), 1.1)), h21(vec2(float(i), 2.2)));
float rad = (0.0015 + h21(vec2(float(i), 3.3)) * 0.0035) * dustSize;
float dd  = length((lp - dp) * vec2(acLayerSize.x / max(acLayerSize.y, 1.0), 1.0));
c -= vec3((1.0 - smoothstep(rad, rad * 1.9, dd)) * dust * 0.75 * on);
}
}

// ---- grain --------------------------------------------------------------
if (grain > 0.001){
vec2 gp = floor(lp * max(acLayerSize.y, 1.0) / max(grainSize, 0.05)) + floor(gT * 24.0) * 7.3;
float n = h21(gp) - 0.5;
c += vec3(n * grain * 0.32);
}

// ---- frame: vignette and light leak ------------------------------------
if (vignette > 0.001){
float asp = acLayerSize.x / max(acLayerSize.y, 1.0);
vec2  q   = vec2((lp.x - 0.5) * asp, lp.y - 0.5) * 2.0;
float r   = length(q) * 0.72;
float vg  = 1.0 - vignette * smoothstep(1.0 - vignetteSoft, 1.35, r);
c *= clamp(vg, 0.0, 1.0);
}

if (lightLeak > 0.001){
float ra = radians(leakAngle);
vec2  ax = vec2(cos(ra), sin(ra));
float g  = dot(lp - vec2(0.5), ax) + 0.5;
float leak = pow(clamp(g, 0.0, 1.0), 2.4);
c += vec3(1.00, 0.72, 0.42) * leak * lightLeak * 0.75;
}

c = sat3v(c);
vec3  col = mix(sc, c, mixAmt);
float oA  = src.a * opacity;
gl_FragColor = vec4(col * oA, oA);
}
